// Look at Weekly SWOT executions and check if any fired by 'trigger' mode in the last 6h.
const resp = $input.first().json;
const rows = Array.isArray(resp) ? resp : (resp.data || []);
const cutoffMs = Date.now() - (6 * 60 * 60 * 1000);
const triggerFires = rows.filter(e => {
  if (e.mode !== 'trigger') return false;
  const t = new Date(e.startedAt || 0).getTime();
  return t >= cutoffMs;
});
const fired = triggerFires.length > 0;
const last = rows[0] || null;
const alertText = fired
  ? `[OK] Weekly SWOT auto-fired (${triggerFires.length} exec em 6h).`
  : `\u{1F6A8} Weekly SWOT NÃO auto-disparou este sábado.\n\n` +
    `Janela verificada: últimas 6h (03:00 - 09:00 UTC / 00:00 - 06:00 SP).\n` +
    `Execs recentes (5): ` + rows.slice(0,5).map(e => `${(e.startedAt||'').slice(0,19)} mode=${e.mode} status=${e.status}`).join(' | ') + `\n\n` +
    `Workflow: 3vQI5AibhbZfDuT7 (Claude Bridge — Weekly SWOT Mac Mini com Memory v2)\n` +
    `Investigar: (a) trigger config tem triggerAtMinute:null? (b) toggle activate necessário? (c) worker n8n vivo?`;
return [{ json: { fired, count: triggerFires.length, last_started: last && last.startedAt, alertText } }];

